// Simple endless runner for canvas with id "game"
(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = canvas.width = 800;
  const H = canvas.height = 200;
  const GRAVITY = 0.6;
  const JUMP_SPEED = -12;

  const player = { x: 50, y: H - 40, w: 30, h: 30, vy: 0, onGround: true };
  const obstacles = [];
  let speed = 4;
  let frame = 0;
  let gameOver = false;

  const spawnObstacle = () => {
    const gap = Math.random() * 120 + 80; // distance between obstacles
    const size = Math.random() * 30 + 20; // obstacle height
    const lastX = obstacles.length ? obstacles[obstacles.length - 1].x : W;
    obstacles.push({ x: lastX + gap, w: 20, h: size });
  };

  const reset = () => {
    obstacles.length = 0;
    player.y = H - player.h;
    player.vy = 0;
    player.onGround = true;
    speed = 4;
    frame = 0;
    gameOver = false;
    spawnObstacle();
    loop();
  };

  const loop = () => {
    if (gameOver) return;
    ctx.clearRect(0, 0, W, H);

    // player physics
    player.vy += GRAVITY;
    player.y += player.vy;
    if (player.y >= H - player.h) {
      player.y = H - player.h;
      player.vy = 0;
      player.onGround = true;
    }
    // draw player
    ctx.fillStyle = '#0a0';
    ctx.fillRect(player.x, player.y, player.w, player.h);

    // obstacles
    ctx.fillStyle = '#a00';
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.x -= speed;
      ctx.fillRect(o.x, H - o.h, o.w, o.h);

      // collision
      if (
        player.x < o.x + o.w &&
        player.x + player.w > o.x &&
        player.y + player.h > H - o.h
      ) {
        gameOver = true;
      }

      // remove passed obstacles
      if (o.x + o.w < 0) obstacles.splice(i, 1);
    }

    // spawn new obstacles
    if (frame % 100 === 0) spawnObstacle();
    frame++;
    speed += 0.001; // gradual speed increase

    if (gameOver) {
      ctx.fillStyle = '#000';
      ctx.font = '30px sans-serif';
      ctx.fillText('Game Over', W / 2 - 80, H / 2);
    } else {
      requestAnimationFrame(loop);
    }
  };

  // input handling
  canvas.addEventListener('pointerdown', () => {
    if (player.onGround && !gameOver) {
      player.vy = JUMP_SPEED;
      player.onGround = false;
    } else if (gameOver) {
      reset();
    }
  });

  // start
  reset();
})();
